import Foundation

public enum CaptureFilter {
    public static let ignoredMarkerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
    ]

    public static let defaultIgnoredApps: [String] = [
        "com.apple.Passwords",
        "com.apple.keychainaccess",
        "com.1password.1password",
        "com.bitwarden.desktop",
    ]

    /// Decides from type names and the source app alone, before any content is read.
    public static func shouldSkip(types: [String], sourceBundleID: String?, ignoredApps: Set<String>) -> Bool {
        if types.contains(where: ignoredMarkerTypes.contains) { return true }
        if let id = sourceBundleID, ignoredApps.contains(id) { return true }
        return false
    }
}
